// Spider fusion: merge a vertex-disjoint MATCHING of same-coloured spiders
// joined by SIMPLE wires in one query; the driver loops to a fixpoint.
//
// The matching is the MUTUAL-MINIMUM-NEIGHBOUR handshake — an edge (a,b) is
// kept iff a's smallest-id same-colour simple neighbour is b AND b's is a.
// Such pairs are vertex-disjoint (each node is the mutual minimum of at
// most one edge), so they fuse simultaneously; and the globally smallest
// fusable endpoint with its smallest neighbour is always such a pair, so
// at least one edge is selected whenever any fusable edge exists (the
// driver loop makes progress). The minimum neighbour is computed in ONE
// aggregation pass (O(E)) instead of the previous O(E^2) `reduce` over an
// accumulating node list, and the edge is processed from its smaller
// endpoint so each matched pair appears exactly once.

MATCH (a:Node)-[:Wire {t: 1}]-(n:Node)
WHERE a.t = n.t AND a.t IN [1, 2]
WITH a, min(id(n)) AS amin
MATCH (a)-[:Wire {t: 1}]-(b:Node)
WHERE id(b) = amin AND id(a) < id(b)
MATCH (b)-[:Wire {t: 1}]-(nb:Node)
WHERE nb.t = b.t AND nb.t IN [1, 2]
WITH a, b, min(id(nb)) AS bmin
WHERE bmin = id(a)
WITH a AS u, b AS v

// Create the merged node with summed phase (unchanged).
CREATE (merged:Node {
  phase: (coalesce(u.phase, 0) + coalesce(v.phase, 0)) % 2,
  t: u.t,
  graph_id: u.graph_id
})
WITH DISTINCT u, v, merged

// Reconnect neighbors of u and v to merged.
OPTIONAL MATCH (u)-[r:Wire]-(x)
WHERE x <> v
FOREACH (_ IN CASE WHEN x IS NOT NULL THEN [1] ELSE [] END |
  CREATE (merged)-[:Wire {t: r.t , graph_id: r.graph_id}]->(x)
)

WITH DISTINCT u, v, merged
OPTIONAL MATCH (v)-[r:Wire]-(y)
WHERE y <> u
FOREACH (_ IN CASE WHEN y IS NOT NULL THEN [1] ELSE [] END |
  CREATE (merged)-[:Wire {t: r.t , graph_id: r.graph_id}]->(y)
)

DETACH DELETE u, v

RETURN COUNT(*) AS merged

// A palette of colors used to color distinct node labels
Define(COLOR_PALETTE, AsArray(
  #DD2222, #FB6E00, #FFC500, #720096,
  #5E4FA2, #3288BD, #66C2A5, #ABDDA4,
  #E6F598, #FEE08B, #D53E4F, #9E0142
))
Define(COLOR_PALETTE_ITER, AsIterator(COLOR_PALETTE))

// If there are no palette colors to use, use random colors instead
Define(RandomColor, Function(RGB(RandomInt(255), RandomInt(255), RandomInt(255))))
Define(GetNextColor, Function(
  Coalesce(Next(COLOR_PALETTE_ITER), RandomColor())
))

// Cache map to keep a selected color for each node label
Define(ColorByLabel, AsMap())
Define(GetColorByLabel, Function(labels, Coalesce(
  Get(ColorByLabel, labels),
  Set(ColorByLabel, labels, GetNextColor())
)))
Define(JoinLabels, Function(labels, Join(Sort(labels), ":")))

// Baseline node style that will be applied to every single node
@NodeStyle {
  Define(COLOR, GetColorByLabel(JoinLabels(Labels(node))))

  size: 6
  color: COLOR
  color-hover: Lighter(COLOR)
  color-selected: Darker(COLOR)
  border-width: 0.6
  border-color: #1D1D1D
  font-size: 3
  font-color: #1D1D1D
}

// Overwrite node text with the node label if defined
@NodeStyle Greater(Size(Labels(node)), 0) {
  label: Format(":{}", Join(Labels(node), " :"))
}

// Overwrite node text with the property "name" if defined
@NodeStyle HasProperty(node, "name") {
  label: AsText(Property(node, "name"))
}

// Feel free to uncomment the lines below to set up a custom style for the specific node label
