// Remove ALL identity spiders (Z or X, phase 0 mod 2, degree 2) in one
// pass, connecting each one's two neighbors with an edge of the combined
// type: s*s = s, s*h = h, h*h = s. Both edges to the SAME neighbor create
// a self-loop instead: a Hadamard self-loop adds pi to that neighbor, a
// simple self-loop is dropped. Rows are processed sequentially, so the
// preconditions are re-checked per row: an earlier removal can rewire a
// later candidate (identity chains) or flip its phase (self-loop pi).

MATCH (cand:Node)
WHERE cand.t IN [1, 2]
  AND cand.phase IS NOT NULL AND cand.phase % 2 = 0
  AND degree(cand) = 2
WITH collect(cand) AS cands
UNWIND cands AS b
MATCH (n1:Node)-[e1:Wire]-(b)-[e2:Wire]-(n2:Node)
WHERE id(e1) < id(e2)
  AND b.phase % 2 = 0 AND degree(b) = 2
  AND n1 <> b AND n2 <> b

WITH b, n1, n2,
     CASE WHEN e1.t = e2.t THEN 1 ELSE 2 END AS new_t

FOREACH (_ IN CASE WHEN n1 <> n2 THEN [1] ELSE [] END |
  CREATE (n1)-[:Wire {t: new_t, graph_id: b.graph_id}]->(n2)
)
FOREACH (_ IN CASE WHEN n1 = n2 AND new_t = 2 THEN [1] ELSE [] END |
  SET n1.phase = (coalesce(n1.phase, 0) + 1) % 2
)

DETACH DELETE b

RETURN count(*) AS identities_removed

