// Boundary pivot (pyzx pivot with one boundary): interior Pauli Z-spider `a`
// H-connected to Pauli Z-spider `b` that touches exactly ONE boundary; all
// other neighbors of both are Z-spiders on Hadamard edges. Performs the full
// pivot: toggles bipartite edges between exclusive/shared neighbor groups,
// copies phases (a's exclusive neighbors get b's phase and vice versa, shared
// get a+b+pi), re-points the boundary wire to `a` with toggled edge type and
// deletes `b` (`a` survives). ONE application per call; the driver loops.
//
// OPTIMIZED: the candidate is found by the SELECTIVE boundary condition
// first (scan the few boundary nodes, not every Pauli pair) and the
// interiorness of a and b is checked with cheap short-circuiting EXISTS
// predicates; the O(degree) neighbour-set collection then runs only for the
// single chosen pivot (after LIMIT 1) instead of for every Pauli-Pauli
// Hadamard edge in the graph.

// b: a Pauli Z-spider touching exactly one boundary (drive from boundaries).
MATCH (bd:Node {t: 0})-[be:Wire]-(b:Node {t: 1})
WHERE b.phase IS NOT NULL AND b.phase % 2 = round(b.phase % 2)
WITH b, collect(DISTINCT bd) AS bds, collect(be) AS bes
WHERE size(bds) = 1
WITH b, bds[0] AS bd, bes[0] AS be

// a: interior Pauli Z-spider Hadamard-connected to b; interiorness of a and
// of b (away from its boundary) via cheap EXISTS, before any collection.
MATCH (a:Node {t: 1})-[pe:Wire {t: 2}]-(b)
WHERE a.phase IS NOT NULL AND a.phase % 2 = round(a.phase % 2)
  AND NOT EXISTS { MATCH (a)-[w:Wire]-(x:Node) WHERE w.t <> 2 OR x.t <> 1 }
  AND NOT EXISTS { MATCH (b)-[w:Wire]-(x:Node)
                   WHERE x.t <> 0 AND (w.t <> 2 OR x.t <> 1) }
WITH a, b, bd, be
ORDER BY id(a), id(b)
LIMIT 1

// Collect the neighbour groups for the chosen pivot only. a is interior so
// all its wires are Hadamard; b's non-boundary neighbours are Z on Hadamard.
OPTIONAL MATCH (a)-[:Wire {t: 2}]-(na:Node)
WHERE na <> b
WITH a, b, bd, be, collect(DISTINCT na) AS a_nbrs
OPTIONAL MATCH (b)-[:Wire {t: 2}]-(nb:Node)
WHERE nb.t <> 0 AND nb <> a
WITH a, b, bd, be, a_nbrs, collect(DISTINCT nb) AS b_zn
WITH a, b, bd, be,
     [x IN a_nbrs WHERE NOT x IN b_zn] AS only_a,
     [x IN b_zn WHERE NOT x IN a_nbrs] AS only_b,
     [x IN a_nbrs WHERE x IN b_zn] AS shared

CALL {
  WITH only_a, only_b
  UNWIND only_a AS u
  UNWIND only_b AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_a, shared
  UNWIND only_a AS u
  UNWIND shared AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

CALL {
  WITH only_b, shared
  UNWIND only_b AS u
  UNWIND shared AS v
  OPTIONAL MATCH (u)-[existing:Wire]-(v)
  FOREACH (_ IN CASE WHEN existing IS NOT NULL THEN [1] ELSE [] END |
    DELETE existing)
  FOREACH (_ IN CASE WHEN existing IS NULL THEN [1] ELSE [] END |
    CREATE (u)-[:Wire {t: 2, graph_id: u.graph_id}]->(v))
}

FOREACH (n IN only_a |
  SET n.phase = (coalesce(n.phase, 0) + b.phase) % 2)
FOREACH (n IN only_b |
  SET n.phase = (coalesce(n.phase, 0) + a.phase) % 2)
FOREACH (n IN shared |
  SET n.phase = (coalesce(n.phase, 0) + a.phase + b.phase + 1) % 2)

// Re-point the boundary wire to a with toggled edge type, delete b.
WITH a, b, bd, CASE be.t WHEN 1 THEN 2 ELSE 1 END AS new_t
CREATE (a)-[:Wire {t: new_t, graph_id: a.graph_id}]->(bd)
DETACH DELETE b

RETURN count(*) AS interior_pauli_removed

