// Between two same-colored spiders, a parallel simple + Hadamard edge pair
// reduces to the simple edge with pi added to one endpoint (fusing along the
// simple edge turns the Hadamard edge into a Hadamard self-loop = pi phase).

MATCH (a:Node)-[s:Wire {t: 1}]-(b:Node), (a)-[h:Wire {t: 2}]-(b)
WHERE id(a) < id(b) AND a.t = b.t AND a.t IN [1, 2]
WITH a, b, head(collect(DISTINCT h)) AS h1
DELETE h1
SET a.phase = (coalesce(a.phase, 0) + 1) % 2
RETURN count(*) AS removed

