// Between two same-colored spiders, parallel simple edges collapse to a
// single simple edge (fusing along one edge turns the others into simple
// self-loops, which vanish).

MATCH (a:Node)-[r:Wire {t: 1}]-(b:Node)
WHERE id(a) < id(b) AND a.t = b.t AND a.t IN [1, 2]
WITH a, b, collect(DISTINCT r) AS rs
WHERE size(rs) >= 2
UNWIND rs[1..] AS r
DELETE r
RETURN count(*) AS removed

