// to_gh step 1 (pyzx to_gh): every wire toggles its type once per X-spider
// endpoint. A wire between two X-spiders toggles twice, i.e. stays put.
// Must run BEFORE the spiders are recolored.

MATCH (a:Node)-[w:Wire]->(b:Node)
WITH w,
     (CASE WHEN a.t = 2 THEN 1 ELSE 0 END) +
     (CASE WHEN b.t = 2 THEN 1 ELSE 0 END) AS x_ends
WHERE x_ends % 2 = 1
SET w.t = CASE w.t WHEN 1 THEN 2 ELSE 1 END
RETURN count(*) AS toggled

