// Cheap detector: are there any parallel wires between same-colored
// spiders (or any multi-edge at all)? Lets the driver skip the three
// parallel-edge normalization queries when there is nothing to do.
MATCH (a:Node)-[r:Wire]-(b:Node)
WHERE id(a) < id(b)
WITH a, b, count(r) AS c
WHERE c > 1
RETURN count(*) AS k

